#include <flat_map>
#include <string>

void Example() {
  std::flat_map<int, std::string> aliases{{10, "admin"}};
  auto saved = aliases.at(10); // самостоятельная строка
  aliases[30] = "editor";
  // saved не обращается к памяти контейнера.
}

#include <map>
#include <string>

int ReadDetached(std::map<std::string, int>& counts) {
  auto detached = counts.extract("draft");
  if (detached.empty()) return -1;
  return detached.mapped();
  // При выходе невставленный узел уничтожается вместе с detached.
}

