#include <string>
#include <unordered_map>

struct Payload { std::string label; };
void Inspect(const std::unordered_map<int, Payload>& entries) {
  const auto pos = entries.find(17);
  if (pos == entries.end()) return;
  const auto& entry = *pos;
  const auto& key = entry.first;
  const auto& data = entry.second;
  (void)key;
  (void)data;
}

#include <cassert>
#include <unordered_map>

void Observe() {
  std::unordered_map<int, int> table{{3, 30}, {7, 70}};
  const auto elements = table.size();
  const auto buckets = table.bucket_count();
  assert(elements == 2);
  assert(buckets > 0);
  // Не сравниваем buckets с точной константой и не считаем их элементами.
}

#include <cassert>
#include <string>
#include <vector>

void Grow() {
  std::vector<std::string> labels(2, "draft");
  labels.resize(4, "new");
  assert(labels.size() == 4);
  assert(labels.at(3) == "new");
}
